from collections import deque

def bfs(graph: dict[str, list[str]], start: str) -> list[str]:
    visited: set[str] = {start}
    queue: deque[str] = deque([start])
    order: list[str] = []

    while queue:
        vertex = queue.popleft()   # FIFO: process oldest-enqueued first
        order.append(vertex)
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return order

# Shortest path (unweighted graph)
def bfs_shortest_path(
    graph: dict[str, list[str]], start: str, end: str
) -> list[str] | None:
    parent: dict[str, str | None] = {start: None}
    queue: deque[str] = deque([start])
    while queue:
        vertex = queue.popleft()
        if vertex == end:
            path = []
            while vertex is not None:
                path.append(vertex)
                vertex = parent[vertex]  # type: ignore
            return path[::-1]
        for neighbor in graph[vertex]:
            if neighbor not in parent:
                parent[neighbor] = vertex
                queue.append(neighbor)
    return None   # no path exists

# Recursive DFS
def dfs_recursive(
    graph: dict[str, list[str]],
    vertex: str,
    visited: set[str] | None = None
) -> list[str]:
    if visited is None:
        visited = set()
    visited.add(vertex)
    result = [vertex]
    for neighbor in graph[vertex]:
        if neighbor not in visited:
            result.extend(dfs_recursive(graph, neighbor, visited))
    return result

# Iterative DFS (explicit stack — safe for large graphs)
def dfs_iterative(
    graph: dict[str, list[str]], start: str
) -> list[str]:
    visited: set[str] = set()
    stack: list[str] = [start]
    result: list[str] = []

    while stack:
        vertex = stack.pop()          # LIFO: dive deep first
        if vertex in visited:
            continue
        visited.add(vertex)
        result.append(vertex)
        # Push neighbors in reverse order to match recursive order
        for neighbor in reversed(graph[vertex]):
            if neighbor not in visited:
                stack.append(neighbor)

    return result

def has_cycle_directed(graph: dict[int, list[int]], V: int) -> bool:
    color = [0] * V   # 0=white, 1=gray, 2=black

    def dfs(v: int) -> bool:
        color[v] = 1   # mark gray: currently on stack
        for neighbor in graph.get(v, []):
            if color[neighbor] == 1:   # back edge → cycle!
                return True
            if color[neighbor] == 0 and dfs(neighbor):
                return True
        color[v] = 2   # mark black: done
        return False

    return any(dfs(v) for v in range(V) if color[v] == 0)

# For undirected graphs: simpler — just track parent
def has_cycle_undirected(
    graph: dict[int, list[int]], V: int
) -> bool:
    visited = [False] * V

    def dfs(v: int, parent: int) -> bool:
        visited[v] = True
        for neighbor in graph.get(v, []):
            if not visited[neighbor]:
                if dfs(neighbor, v):
                    return True
            elif neighbor != parent:   # found a cycle
                return True
        return False

    return any(dfs(v, -1) for v in range(V) if not visited[v])

from collections import defaultdict, deque

# Kahn's Algorithm (BFS-based) — also detects cycles
def topological_sort_kahn(
    graph: dict[str, list[str]], vertices: list[str]
) -> list[str] | None:
    in_degree: dict[str, int] = {v: 0 for v in vertices}
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    queue: deque[str] = deque(v for v in vertices if in_degree[v] == 0)
    result: list[str] = []

    while queue:
        v = queue.popleft()
        result.append(v)
        for neighbor in graph.get(v, []):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result if len(result) == len(vertices) else None  # None = cycle

# DFS-based topological sort
def topological_sort_dfs(
    graph: dict[str, list[str]], vertices: list[str]
) -> list[str]:
    visited: set[str] = set()
    result: list[str] = []

    def dfs(v: str) -> None:
        visited.add(v)
        for neighbor in graph.get(v, []):
            if neighbor not in visited:
                dfs(neighbor)
        result.append(v)   # append AFTER all descendants are done

    for v in vertices:
        if v not in visited:
            dfs(v)

    return result[::-1]   # reverse post-order = topological order

import heapq
from collections import defaultdict

def dijkstra(
    graph: dict[str, list[tuple[str, int]]], source: str
) -> dict[str, float]:
    dist: dict[str, float] = defaultdict(lambda: float('inf'))
    dist[source] = 0
    heap: list[tuple[float, str]] = [(0, source)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue    # stale entry — skip
        for v, weight in graph[u]:
            new_dist = dist[u] + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))

    return dict(dist)

# Example: road map
