def bellman_ford(
    vertices: list[str],
    edges: list[tuple[str, str, int]],   # (u, v, weight)
    source: str
) -> dict[str, float] | None:
    dist: dict[str, float] = {v: float('inf') for v in vertices}
    dist[source] = 0

    # Relax all edges V-1 times
    for _ in range(len(vertices) - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    # V-th pass: if any edge still relaxes, there's a negative cycle
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            return None   # negative-weight cycle detected

    return dist

