# Kruskal's Algorithm — sort edges, add if no cycle (Union-Find)
def kruskal(
    V: int, edges: list[tuple[int, int, int]]   # (weight, u, v)
) -> list[tuple[int, int, int]]:
    edges.sort()                  # sort by weight
    parent = list(range(V))

    def find(x: int) -> int:      # path-compressed find
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> bool:
        rx, ry = find(x), find(y)
        if rx == ry: return False  # same component — would create cycle
        parent[rx] = ry
        return True

    mst: list[tuple[int, int, int]] = []
    for w, u, v in edges:
        if union(u, v):
            mst.append((w, u, v))
            if len(mst) == V - 1:
                break
    return mst

# Prim's Algorithm — grow MST from source using min-heap
import heapq

def prim(
    graph: dict[int, list[tuple[int, int]]],  # {u: [(v, weight)]}
    V: int
) -> list[tuple[int, int, int]]:
    in_mst = [False] * V
    heap: list[tuple[int, int, int]] = [(0, 0, -1)]  # (weight, v, u)
    mst: list[tuple[int, int, int]] = []

    while heap and len(mst) < V - 1:
        w, v, u = heapq.heappop(heap)
        if in_mst[v]: continue
        in_mst[v] = True
        if u != -1: mst.append((w, u, v))
        for neighbor, weight in graph.get(v, []):
            if not in_mst[neighbor]:
                heapq.heappush(heap, (weight, neighbor, v))
    return mst

class UnionFind:
    def __init__(self, n: int) -> None:
        self.parent = list(range(n))
        self.rank = [0] * n
        self.components = n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # path compression
        return self.parent[x]

    def union(self, x: int, y: int) -> bool:
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False   # already connected
        # Union by rank: attach smaller tree under larger
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1
        self.components -= 1
        return True

    def connected(self, x: int, y: int) -> bool:
        return self.find(x) == self.find(y)

# Example: count components after adding edges
uf = UnionFind(6)   # vertices 0..5, 6 components initially
uf.union(0, 1)
uf.union(1, 2)
uf.union(3, 4)
print(uf.components)       # 3  (groups: {0,1,2}, {3,4}, {5})
print(uf.connected(0, 2))  # True
print(uf.connected(0, 3))  # False
